PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE competitions (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE competition_backups (
  id TEXT PRIMARY KEY,
  competition_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  document TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE logs (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE login_attempts (
  address TEXT PRIMARY KEY,
  failures INTEGER NOT NULL,
  blocked_until INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE people (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, statistics_updated_at TEXT);
CREATE TABLE avatars (
  key TEXT PRIMARY KEY,
  body BLOB NOT NULL,
  content_type TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE tutorial_case_states (
  id TEXT PRIMARY KEY,
  document TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE stats_snapshots (
  id TEXT PRIMARY KEY,
  version TEXT NOT NULL,
  document TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE club_registrations (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL COLLATE NOCASE UNIQUE,
  nickname TEXT NOT NULL,
  qq TEXT NOT NULL,
  majsoul_id TEXT NOT NULL COLLATE NOCASE UNIQUE,
  current_rank TEXT NOT NULL,
  goals TEXT NOT NULL,
  account_ownership_confirmed INTEGER NOT NULL CHECK (account_ownership_confirmed = 1),
  privacy_consent INTEGER NOT NULL CHECK (privacy_consent = 1),
  created_at TEXT NOT NULL
, majsoul_nickname TEXT NOT NULL DEFAULT '', other_platform_rank TEXT NOT NULL DEFAULT '');
DELETE FROM sqlite_sequence;
CREATE INDEX competition_backups_competition_created
  ON competition_backups (competition_id, created_at DESC);
CREATE INDEX tutorial_case_states_updated
  ON tutorial_case_states (updated_at DESC);
CREATE INDEX club_registrations_created_at
  ON club_registrations (created_at DESC);
